insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'میں عمر (رضی اللہ عنہ) دے نال عید دی نماز وچ حاضر ہویا، اوہناں نے خطبے توں پہلاں نماز پڑھائی، فیر کہیا: رسول اللہ صلی اللہ علیہ وسلم نے ایہناں دو دنیں روزہ رکھن توں منع فرمایا: عید الاضحیٰ دے دن تسیں اپنی قربانی دا گوشت کھاندے او، تے عید الفطر دا دن تہاڈے روزے توڑن دا دن اے۔');
