insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'میں اللہ توں امید رکھدا ہاں کہ عرفہ دے دن دا روزہ پچھلے تے اگلے سال دے گناہاں دا کفارہ ہووے، تے عاشورہ دے دن دا روزہ پچھلے سال دے گناہاں دا کفارہ ہووے۔');
