insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'رسول اللہ صلی اللہ علیہ وسلم ذی الحجہ دے پہلے نو دن، عاشورہ دے دن، تے ہر مہینے وچ تن دن دا روزہ رکھدے سن…');
