insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'تہاڈے لئی ایہ کافی اے کہ تسیں ہر مہینے وچ تن دن روزہ رکھو، کیونکہ ہر نیکی دا بدلہ دس گنا ملدا اے، تے ایہ پورے سال دا روزہ بن جاندا اے۔');
