insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'ہر مہینے وچ تن دن روزہ رکھنا، تے رمضان توں رمضان تک روزہ رکھنا، ایہ سدا دا روزہ اے۔');
