insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'جس نے ہر مہینے وچ تن دن روزہ رکھیا، ایہ عمر بھر دا روزہ اے۔');
