insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'ہر مہینے وچ تن دن دا روزہ عمر بھر دا روزہ اے، تے ایامِ بیض دے روزے: تیرہویں، چودہویں تے پندرہویں۔');
