insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'ابوہریرہ (رضی اللہ عنہ) توں روایت اے:');
insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'میرے پیارے دوست (نبی صلی اللہ علیہ وسلم) نے مینوں تن گلاں دی وصیت کیتی: ہر مہینے وچ تن دن روزہ رکھنا، دو رکعت چاشت دی نماز، تے سون توں پہلاں وتر پڑھنا۔');
