insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'میرے پیارے دوست (نبی صلی اللہ علیہ وسلم) نے مینوں تن ایسیاں گلاں دی وصیت کیتی جہڑیاں میں کدی نئیں چھڈاں گا؛ اوہناں وچوں ہر مہینے وچ تن دن دے روزے نیں۔');
