insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'اے ابوذر! جے تسیں مہینے وچ تن دن روزہ رکھو، تاں تیرہویں، چودہویں تے پندرہویں نوں رکھو۔');
