insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'اسامہ بن زید (رضی اللہ عنہما) توں روایت اے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:');
insert into i18n_bundles (locale, code, value) values ('pa', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'ایہ اوہ دو دن نیں جنہاں وچ جہاناں دے رب دے حضور عمل پیش کیتے جاندے نیں، تے میں پسند کریندا ہاں کہ میرا عمل پیش ہووے تے میں روزے نال ہوواں۔');
